css:
.d1121-old,.d1121-new,.d1121-sit,.d1121-knock{transform-box:fill-box}
.d1121-old{transform-origin:center;animation:d1121-a 3.4s ease-in-out infinite}
.d1121-new{transform-origin:center;animation:d1121-b 3.4s ease-in-out infinite}
.d1121-sit{transform-origin:center;animation:d1121-s 3.4s ease-in-out infinite}
.d1121-knock{transform-origin:center;animation:d1121-k 3.4s ease-in-out infinite}
@keyframes d1121-a{0%,20%{transform:translateX(0)}60%,100%{transform:translateX(-45px)}}
@keyframes d1121-b{0%,20%{transform:translateX(30px)}60%,100%{transform:translateX(-10px)}}
@keyframes d1121-s{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}
@keyframes d1121-k{0%,100%{transform:translateX(0)}40%,60%{transform:translateX(-14px)}}
@media (prefers-reduced-motion:reduce){.d1121-old{transform:translateX(-45px)}.d1121-new{transform:translateX(-10px)}}
